package com.example.complaintmanagement.controller; import com.example.complaintmanagement.dto.CategoryDtos.*; import com.example.complaintmanagement.service.CategoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/categories") public class CategoryController{final CategoryService s;public CategoryController(CategoryService s){this.s=s;} @GetMapping public List<Response> all(){return s.all();}@GetMapping("/{id}")public Response get(@PathVariable Long id){return s.get(id);}@PostMapping public ResponseEntity<Response> create(@Valid @RequestBody Request r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}")public Response update(@PathVariable Long id,@Valid @RequestBody Request r){return s.update(id,r);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}